    println!("3 static mut: {hits}");
    println!("4 unsafe trait: {}", zeroed::<u32>());
    let bits = Bits { float: 1.0 };
    // SAFETY: every 4-byte pattern is a valid u32
    let int = unsafe { bits.int };
    println!("5 union field: {int}");
